fn rolling_max(s: &Vec<i8>) -> Option<i8> {
    if s.len() < 2 {
        return None;
    }

    // max1 holds the largest value seen so far,
    // max2 holds the second‐largest (with duplicates).
    let mut max1 = i8::MIN;
    let mut max2 = i8::MIN;

    for &x in s.iter() {
        if x >= max1 {
            // x becomes the new max1, and the old max1
            // demotes to max2
            max2 = max1;
            max1 = x;
        } else if x > max2 {
            // x lies strictly between max1 and max2
            max2 = x;
        }
    }

    Some(max2)
}

